import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
test('report', () => {
  const md = readFileSync(new URL('../report.md', import.meta.url), 'utf8');
  assert.match(md, /^# Orders by customer/m);
  const rows = md.split('\n').filter((l) => l.trim().startsWith('|')).map((l) => l.split('|').slice(1, -1).map((c) => c.trim()));
  const body = rows.filter((r) => !/^:?-+:?$/.test(r[0]) && r[0] !== 'Customer');
  assert.deepEqual(body, [
    ['Harbour Cafe', '2', '$1,234.50'],
    ['Bondi Bakes', '2', '$99.99'],
    ['Newtown Noodles', '1', '$45.25'],
    ['**All**', '5', '$1,379.74'],
  ]);
});

solution.report.js:
import { readFileSync, writeFileSync } from 'node:fs';
const orders = JSON.parse(readFileSync(new URL('./data/orders.json', import.meta.url), 'utf8')).filter((o) => o.status !== 'cancelled');
const by = new Map();
for (const o of orders) {
  const c = by.get(o.customer) ?? { n: 0, t: 0 };
  c.n++; c.t += o.total;
  by.set(o.customer, c);
}
const money = (x) => '$' + x.toLocaleString('en-AU', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const rows = [...by].sort((a, b) => b[1].t - a[1].t).map(([c, v]) => `| ${c} | ${v.n} | ${money(v.t)} |`);
const all = orders.reduce((s, o) => s + o.total, 0);
writeFileSync(new URL('./report.md', import.meta.url), ['# Orders by customer', '', '| Customer | Orders | Total |', '| --- | --- | --- |', ...rows, `| **All** | ${orders.length} | ${money(all)} |`, ''].join('\n'));
